    var step6 = 'a72db2ae831ec7101902ba96feaad35c';
	var scReqItemTbl = 'sc_req_item';

    // 1. Get the Sys ID of the RITM found in Step 6
    var ritmSysId = steps(step6).first_record;

    // 2. Query the actual RITM table to verify its final state and grab parent info
    var ritmGr = new GlideRecord(scReqItemTbl);
    if (ritmGr.get(ritmSysId)) {

        var currentRitmState = ritmGr.state.getDisplayValue();
        var ritmNumber = ritmGr.getValue('number');
        var parentRequestNumber = ritmGr.request.number.getDisplayValue(); // Extracts REQ number

        // 3. Confirm it matches "Closed Skipped"
        if (currentRitmState == 'Closed Skipped' || ritmGr.state == 7) {

            // 4. FORMATTED OUTPUT: Displays REQ, RITM, and Sys ID clearly on pass
            var visualConfirmation = 'REJECTION VERIFIED >> Request: [' + parentRequestNumber + '] | RITM: [' + ritmNumber + '] | Sys ID: [' + ritmSysId + '] | Final State: [' + currentRitmState + ']';

            stepResult.setOutputMessage(visualConfirmation);
            stepResult.setSuccess();

        } else {
            stepResult.setOutputMessage('Validation Failed: RITM is in state [' + currentRitmState + '], expected Closed Skipped.');
            stepResult.setFailed();
        }
    } else {
        stepResult.setOutputMessage('Error: Could not locate the original RITM record.');
        stepResult.setFailed();
